  // the real list price and the retention discount can get its OWN negative
  // line beneath it — same reasoning as the extra-disk/backup lines: a
  // customer should be able to see exactly what was discounted, not just a
  // smaller total with no explanation.
  const preRetentionNetCents = netCents + retentionDiscountCents;

  // `renewalCharge` bills `vpsTermPriceCents` (or a game plan's flat price) with NO
  // seasonal promo — renewals never get the intro discount, exactly as
  // lib/promotions.ts promises. So the months this renewal adds were sold at 0% off
  // and the term's stored rate basis must say so, or a later downgrade credits them
  // at a promo rate nobody was ever charged. Blended rather than overwritten for the
  // same reason as renewNow: this sweep only fires on already-expired servers (so
  // the blend is 0 in practice), but the shared helper means the two renewal paths
  // cannot express different rules for the same event.
  const renewedPercent = prorateBlendPercent({
    currentPercent: resolveTermPromoPercent(server.termPromoPercent),
    currentMonths: remainingMonths(server.expiresAt, Date.now()),
    addedPercent: 0,
    addedMonths: charge.months,
  });

  try {
    await db.$transaction(async (tx) => {
      const advanced = await tx.server.updateMany({
        where: { id: server.id, expiresAt: server.expiresAt },
        data: {
          expiresAt: newExpiry,
          termPromoPercent: renewedPercent,
          // The period is paid, so the collection state that belonged to it dies
          // with it. Leaving a stage behind would hand the NEXT period a
          // half-spent retry budget and the wrong dunning email.
          dunningStage: 0,
          dunningNextAt: null,
          dunningPayUrl: null,
          // RETENTION OFFER: this renewal is the "very next" one the discount was
          // promised for — spent or not (retentionDiscountCents is 0 on every
          // server that never had one pending), it is cleared HERE, in the same
          // CAS-guarded write that advances the period, so it can never silently
          // reapply to the period after this one. A losing/replayed pass matches
          // zero rows (the `where: expiresAt: server.expiresAt` guard) and clears
          // nothing, so a retried sweep can't burn the discount without actually
          // renewing.
          pendingRenewalDiscountPercent: null,
        },
      });
      if (advanced.count === 0) throw new AlreadyRenewedError();
      await debitWallet(tx, server.userId, renewCents);
      await tx.walletTransaction.create({
        data: {
          userId: server.userId,
          amountCents: -renewCents,
          description: `Renewal: ${charge.label} (${server.hostname})`,
        },
      });
      // PAID invoice for this renewal period. Inside the CAS-guarded tx, so a
      // retried/concurrent sweep hits AlreadyRenewedError and rolls back —
      // never producing a second invoice for the same period.
      const renewalInvoice = await tx.invoice.create({
        data: invoiceCreateData({
          userId: server.userId,
          description: `Renewal: ${charge.label} (${server.hostname})`,
          status: "PAID",
          // Snapshot the card on file at charge time (null-safe for wallet-only users).
          paidBrand: server.user.cardBrand ?? null,
          paidLast4: server.user.cardLast4 ?? null,
          // VAT recorded separately; the line items below sum to the NET (netCents).
          taxCents,
          taxRatePercent,
          taxCountry: taxCountry ?? null,
          period: { start: periodStart, end: newExpiry },
          // Extra disk gets its OWN line so the customer sees exactly what the
          // permanent storage costs each cycle; the lines sum back to netCents.
          lineItems: [
            {
              description: `${charge.label} — ${server.hostname}`,
              qty: 1,
              unitCents: preRetentionNetCents - extraDiskCents - backupCents,
              amountCents: preRetentionNetCents - extraDiskCents - backupCents,
            },
            ...(extraDiskCents > 0
              ? [
                  {
                    description: `${extraDiskLabel(server.extraDiskGB)} — ${server.hostname} (permanent, $${(extraDiskMonthlyCents / 100).toFixed(2)}/mo)`,
                    qty: 1,
                    unitCents: extraDiskCents,
                    amountCents: extraDiskCents,
                  },
                ]
              : []),
            // Paid backup retention (Plus) gets its own line, mirroring extra disk,
            // so the customer sees exactly what the retention upsell costs each cycle.
            ...(backupCents > 0
              ? [
                  {
                    description: `Plus backups (keep 7) — ${server.hostname} ($${(backupMonthlyCents / 100).toFixed(2)}/mo)`,
                    qty: 1,
                    unitCents: backupCents,
                    amountCents: backupCents,
                  },
                ]
              : []),
            // The one-time retention offer, its OWN (negative) line so the customer
            // sees exactly what "stay and save" bought them on this one renewal —
            // never on any other, since `pendingRenewalDiscountPercent` was just
            // cleared above.
            ...(retentionDiscountCents > 0
              ? [
                  {
                    description: `Retention offer — 50% off this renewal (${server.hostname})`,
                    qty: 1,
                    unitCents: -retentionDiscountCents,
                    amountCents: -retentionDiscountCents,
                  },
                ]
              : []),
          ],
        }),
      });
      renewedInvoice = {
        id: renewalInvoice.id,
        number: renewalInvoice.number,
        amountCents: renewalInvoice.amountCents,
      };
      await tx.auditLog.create({
        data: { userId: server.userId, action: "billing.renewed", detail: server.id },
      });
      // First-month-free conversion: this is the server's SECOND term. Flip the
      // redemption anchored to it to renewed (idempotent, same tx as the money).
      await markPromoRenewed(tx, server.id);
    });
  } catch (e) {
    if (e instanceof InsufficientBalanceError) {
      console.log(`[billing] insufficient balance for ${server.hostname} — falling through to grace/suspend`);
      return "insufficient";
    }
    if (e instanceof AlreadyRenewedError) return "already"; // someone else advanced the period
    throw e;
  }

  // The period is settled. Any 3-D Secure challenge still hanging off it is a
  // loaded gun: anything that later confirms that intent takes a SECOND payment
  // for a period we have already been paid for. Only worth a Stripe round-trip
  // when this server was actually mid-dunning.
  if (server.dunningStage > 0 || server.dunningPayUrl) {
    await cancelPendingChargeForMarker(
      server.user.stripeCustomerId,
      renewalChargeMarker(server.id, periodStart),
    );
  }

  // A settled period ends the reminder cycle: clear the card-less renewal reminder
  // so the NEXT approach-to-expiry can remind once more. Guarded on the in-memory
  // flag so the wallet-only majority skip the write, and best-effort so this
  // housekeeping can never unwind a renewal that already committed.
  if (reminderSentAt(server)) {
    await reminderServer()
      .update({ where: { id: server.id }, data: { renewalReminderSentAt: null } })
      .catch(() => {});
  }

  // Email the renewal INVOICE with its PDF attached. Best-effort and post-commit —
  // the term is already settled, so a mail failure must never unwind a renewal.
  // Fires exactly once per successful renewal because this is the single "renewed"
  // exit of the CAS-guarded commit, reached by BOTH the wallet-only path and the
  // card path. Deliberately `invoiceNew` (subject "Invoice #… — $… due"), NOT
  // `receipt`: a card renewal already gets a distinct card-charge paymentReceipt
  // above, and a second "Payment received — $…" would duplicate it — this is the
  // invoice document instead. `kind:"invoice"` is ACCOUNT-tier (suppressible), and
  // the `invoice_new` template is in the mailer's attach set, so the PDF attaches.
  // Read via the declared union — the value is assigned inside the $transaction
  // callback, which TS control-flow analysis does not track, so a direct read would
  // narrow to `null`.
  const invForEmail = renewedInvoice as { id: string; number: number; amountCents: number } | null;
  if (invForEmail) {
    try {
      const branding = await invoiceBranding();
      await mail(
        server.user.email,
        server.userId,
        emails.invoiceNew(
          {
            invoiceNumber: formatInvoiceNumber(invForEmail.number, branding.numberPrefix),
            amount: fmtUsd(invForEmail.amountCents),
            dueDate: fmtDay(new Date()),
            description: `${charge.label} — ${server.hostname}`,
          },
          true, // the itemised PDF is attached (invoiceId passed below)
        ),
        "invoice",
        invForEmail.id,
      );
    } catch (e) {
      console.error("[billing] renewal invoice email failed", e);
    }
  }
  return "renewed";
}

/**
 * Charge the saved card for the wallet shortfall, then renew.
 *
 * The card NEVER pays the invoice directly. It credits the wallet with exactly
 * what Stripe captured, and `commitRenewal` then debits the FULL renewal from the
 * wallet — identical to how checkout splits a purchase. That ordering is what
 * makes a crash safe in both directions: money captured but not yet applied sits
 * in the customer's wallet as credit (visible, spendable, refundable), and a
 * renewal can never be granted without a matching debit.
 *
 * TWO idempotency guards ride on every attempt:
 *  - `marker` (server + period) — a permanent pre-flight lookup at Stripe for a
 *    live PaymentIntent for this exact period, so a crash between "Stripe captured"
 *    and "we recorded it" replays instead of charging again.
 *  - `idempotencyKey` (server + period + attempt + amount) — Stripe replays an
 *    identical request for 24h, which covers two overlapping sweeps of the SAME
 *    scheduled attempt. The attempt and amount are in the key because a genuine
 *    day-3 retry, or a retry for a different remainder after the wallet moved, is a
 *    deliberately NEW charge; reusing the key there would make Stripe reject it.
 *
 * And the credit itself is guarded by the UNIQUE index on
 * `WalletTransaction.stripePaymentIntentId`, so even a replayed capture credits once.
 *
 * @returns true when the term was actually extended.
 */
async function attemptCardRenewal(opts: {
  server: DueServer;
  charge: RenewalCharge;
  cardCents: number;

  cardCents: number;
  newExpiry: Date;
  now: Date;
  cfg: DunningConfig;
  /** Destination country the VAT was charged for; passed through to the invoice. */
  taxCountry?: string;
}): Promise<boolean> {
  const { server, charge, cardCents, newExpiry, now, cfg, taxCountry } = opts;
  const user = server.user;
  const periodStart = server.expiresAt!;
  const marker = renewalChargeMarker(server.id, periodStart);
  const idempotencyKey = `nxeon_renew_${server.id}_${periodStart.getTime()}_a${server.dunningStage}_${cardCents}`;
  const cardLabel = savedCardLabel(user) ?? "your saved card";

  const result = await chargeSavedCardOffSession({
    user,
    amountCents: cardCents,
    description: `Renewal: ${charge.label} (${server.hostname})`,
    marker,
    idempotencyKey,
    metadata: {
      nxeonServerId: server.id,
      nxeonPeriodStart: periodStart.toISOString(),
      nxeonKind: "renewal",
    },
  });

  if (result.ok) {
    // Exactly what Stripe took, not what we asked for — a replayed intent can carry
    // an older amount and the ledger must match the bank, not our intent.
    const credited = await creditOffSessionCharge({
      userId: server.userId,
      amountCents: result.amountCents,
      description: `Card payment for ${server.hostname} renewal (${cardLabel})`,
      paymentIntentId: result.paymentIntentId,
      // No invoice for the card leg: `commitRenewal` issues ONE paid invoice for
      // the whole renewal, and a second document for the card portion would
      // double-count the same revenue.
    });
    const outcome = await commitRenewal({ server, charge, newExpiry, taxCountry });

    // The receipt is tied to the CREDIT, not the renewal: `creditOffSessionCharge`
    // returns false on the P2002 that means "already credited", so a replayed
    // capture cannot email the same customer a second receipt for one charge.
    if (credited) {
      await mail(
        user.email,
        user.id,
        emails.paymentReceipt(
          fmtUsd(result.amountCents),
          `${charge.label} — ${server.hostname}`,
          user.cardLast4 ?? "",
        ),
        // ACCOUNT tier — a receipt is the one mail from this sweep a customer may
        // legitimately opt out of. Everything else here is CRITICAL by default.
        "receipt",
      );
    }

    if (outcome === "insufficient") {
      // The card paid, the wallet was credited, and the debit STILL failed — the
      // customer spent the credit between our split read and the transaction. The
      // money is not lost, it is sitting in their wallet; re-run shortly rather
      // than charging again (the marker replays this same capture, so the next
      // pass cannot take a second payment) and do NOT count it as a dunning
      // failure, because nothing about their card went wrong.
      console.error(
        `[billing] ${server.hostname}: card captured ${fmtUsd(result.amountCents)} but the wallet debit fell short — retrying shortly`,
      );
      await rescheduleAttempt(server, new Date(now.getTime() + TRANSIENT_RETRY_MS));
      return false;
    }
    if (outcome === "renewed") {
      console.log(
        `[billing] renewed ${server.hostname} until ${newExpiry.toISOString()} (card ${fmtUsd(result.amountCents)}${result.replayed ? ", replayed" : ""})`,
      );
    }
    return true;
  }

  if (result.kind === "transient") {
    // Our side or Stripe's side wobbled. Never a dunning event: a misclassified
    // transient costs a delayed renewal, a misclassified decline costs a paid-up
    // customer their server. The attempt counter is untouched.
    console.warn(`[billing] transient charge error for ${server.hostname}: ${result.message}`);
    await rescheduleAttempt(server, new Date(now.getTime() + TRANSIENT_RETRY_MS));
    return false;
  }

  if (result.kind === "unavailable") {
    // `hasChargeableCard` already proved Stripe is configured and both ids are
    // present, and `walletSplit` keeps the amount above Stripe's floor — so the
    // only way here is `resource_missing`: the payment method no longer exists at
    // Stripe. Not a decline; there is nothing to retry until a new card is saved.
    // Clearing the columns matters twice over: the portal stops claiming a card is
    // on file, and `suspendDueAt` stops granting card-customer runway to an account
    // that has no card at all.
    console.warn(`[billing] saved card unusable for ${server.hostname}: ${result.message}`);
    await forgetMissingPaymentMethod(server.userId).catch((e) =>
      console.error("[billing] could not clear missing payment method", e),
    );
    // `server.user` is deliberately NOT mutated: this pass keeps the card-customer
    // runway and only the NEXT pass falls back to the shorter no-card grace. More
    // runway is always the safe direction for a fault the customer never saw coming.
    await rescheduleAttempt(server, null);
    await notify(
      server.userId,
      "Your saved card is no longer available",
      `We couldn't use the card saved for ${server.hostname} — your bank or Stripe no longer recognises it. Add a card to keep your services renewing automatically.`,
      "/dashboard/billing",
    );
    return false;
  }

  if (result.kind === "requires_action") {
    // 3-D Secure. Off-session there is no browser to satisfy the challenge, so the
    // answer is a hosted Checkout link: the customer completes the bank step on
    // Stripe's own page, the money lands as wallet credit and the next sweep
    // renews from the wallet. This is NOT a decline — nothing about the card is
    // wrong — so it must never consume a retry, or a customer who simply hasn't
    // opened their email yet would be dunned toward suspension for their bank's
    // security policy.
    let payUrl = server.dunningPayUrl;
    if (!payUrl) {
      payUrl = await createOutstandingCheckout({
        user,
        amountCents: cardCents,
        hostname: server.hostname,
        serverId: server.id,
      });
      if (payUrl) {
        await db.server.update({ where: { id: server.id }, data: { dunningPayUrl: payUrl } });
        await mail(
          user.email,
          user.id,
          emails.paymentActionRequired(server.hostname, fmtUsd(cardCents), payUrl),
        );
        await notify(
          server.userId,
          `${server.hostname} — your bank needs to confirm the payment`,
          `Your card issuer asked for an extra verification step for ${fmtUsd(cardCents)}. Confirming it finishes the renewal. Nothing is suspended.`,
          `/dashboard/servers/${server.id}`,
        );
      }
    }
    // Re-check daily rather than hourly: the challenge does not move, and the same
    // link is already in their inbox. `dunningPayUrl` being set is what stops the
    // email repeating for this period; `clearStaleDunning`/`commitRenewal` clear it.
    server.dunningPayUrl = payUrl;
    await rescheduleAttempt(server, new Date(now.getTime() + MIN_RETRY_GAP_MS));
    console.log(`[billing] ${server.hostname} awaiting 3-D Secure confirmation for ${fmtUsd(cardCents)}`);
    return false;
  }

  // Hard decline — the issuer said no. This is the only outcome that spends an
  // attempt and moves the customer along the dunning sequence.
  await recordDeclinedAttempt({ server, cardCents, now, cfg, reason: result.message });
  return false;
}

/**
 * The PayPal analogue of `attemptCardRenewal`, for a customer with a vaulted
 * PayPal method but no saved card. Same money model (charge the shortfall,
 * credit the wallet for exactly what was taken, `commitRenewal` debits the
 * FULL renewal from the wallet) and the same dunning cadence/schedule — only
 * gated separately behind `renewals_paypal_fallback_enabled` (see
 * `renewDueServer`'s `paypalInPlay`) since the underlying charge path
 * (`chargeVaultedPayPalOffSession`) has not yet been exercised against a real
 * PayPal charge from this codebase.
 *
 * IDEMPOTENCY differs from the card path: PayPal's Orders API has no
 * equivalent to Stripe's `paymentIntents.list({customer, ...})` metadata
 * search, so there is no durable pre-flight "did we already charge this
 * period" lookup at PayPal's end. Instead, `marker` is embedded in the
 * WalletTransaction description written by `creditOffSessionCharge` on
 * success, and checked here FIRST — a crash between "PayPal captured" and
 * "we recorded the credit" therefore still cannot double-charge, because a
 * retried pass finds its own prior credit before ever calling PayPal again.
 * `idempotencyKey` still drives PayPal's own short-lived request-replay
 * protection for the case where two sweeps genuinely overlap within it.
 *
 * @returns true when the term was actually extended.
 */
async function attemptPayPalRenewal(opts: {
  server: DueServer;
  charge: RenewalCharge;

async function recordDeclinedAttempt(opts: {
  server: DueServer;
  cardCents: number;
  now: Date;
  cfg: DunningConfig;
  reason: string;
  /** Which rail declined — selects the email copy below. Card is the default
   *  so every existing (Stripe) call site is unchanged. */
  method?: "card" | "paypal";
}): Promise<void> {
  const { server, cardCents, now, cfg, reason, method = "card" } = opts;
  const prevStage = server.dunningStage;
  const newStage = Math.min(prevStage + 1, DUNNING_EXHAUSTED);
  const amount = fmtUsd(cardCents);
  const last4 = server.user.cardLast4 ?? "";

  console.warn(`[billing] card declined for ${server.hostname} (attempt ${newStage}): ${reason}`);

  const calendarSuspendAt = new Date(
    server.expiresAt!.getTime() + calendarSuspendDay(cfg, true) * DAY,
  );

  if (prevStage >= DUNNING_EXHAUSTED) {
    // Already out of attempts; this was the extra try granted either by the stored
    // suspension time arriving or by `retryDunningNow` after the customer saved a
    // new card. Silent — they have already had the final notice, and a second copy
    // of it would be noise.
    //
    // The schedule drops back to the plain calendar deadline (already in the past by
    // now), so this attempt CANNOT defer the suspension it precedes. When the admin
    // kill switch is off nothing will ever be suspended, so fall back to a daily
    // cadence instead — otherwise a 10-minute sweep would attempt the same declining
    // card every 10 minutes forever, which is exactly how an issuer starts blocking
    // us outright.
    await rescheduleAttempt(
      server,
      cfg.autoSuspend ? calendarSuspendAt : new Date(now.getTime() + MIN_RETRY_GAP_MS),
    );
    return;
  }

  // Where the customer is told to expect us next. While retries remain that is the
  // next attempt; once they are spent it is the ONE CLEAR DAY the final notice
  // promises — measured from this moment, not from expiry, so a sequence that ran
  // late (worker downtime) still gets its full day instead of being suspended in the
  // same pass that told the customer it was their last chance.
  const scheduledAt =
    nextRetryAt(server.expiresAt!, newStage, now) ??
    new Date(Math.max(calendarSuspendAt.getTime(), now.getTime() + DAY));
  // The date quoted in the email is derived from the state we are about to WRITE,
  // never from the row we read — `suspendDueAt` honours `dunningNextAt`, so quoting
  // the pre-update value would print a day earlier than the sweep actually acts on.
  const suspendAt =
    suspendDueAt(
      { expiresAt: server.expiresAt, dunningStage: newStage, dunningNextAt: scheduledAt },
      true,
      cfg,
    ) ?? calendarSuspendAt;

  await db.server.update({
    where: { id: server.id },
    data: { dunningStage: newStage, dunningNextAt: scheduledAt },
  });
  server.dunningStage = newStage;
  server.dunningNextAt = scheduledAt;

  await db.auditLog
    .create({
      data: {
        userId: server.userId,
        action: "billing.card_declined",
        detail: `${server.id}: attempt ${newStage} for ${amount} — ${reason.slice(0, 180)}`,
      },
    })
    .catch(() => {
      /* audit is bookkeeping; never let it break collection */
    });

  if (newStage === 1) {
    // FIRST failure of the period. Five-positional-string overload — the object
    // form is the legacy catalog shape used by the admin template previewer.
    await mail(
      server.user.email,
      server.userId,
      method === "paypal"
        ? emails.paypalPaymentFailed(server.hostname, amount, fmtDay(scheduledAt), billingUrl())
        : emails.paymentFailed(server.hostname, amount, last4, fmtDay(scheduledAt), billingUrl()),
    );
  } else if (newStage < DUNNING_EXHAUSTED) {
    // `attempt` counts RETRIES (the expiry-day attempt is attempt 0), which is what
    // `emails.paymentRetryFailed` subtracts from DUNNING_RETRY_ATTEMPTS to tell the
    // customer how many tries are left.
    await mail(
      server.user.email,
      server.userId,
      method === "paypal"
        ? emails.paypalPaymentRetryFailed(server.hostname, amount, newStage - 1, fmtDay(suspendAt), billingUrl())
        : emails.paymentRetryFailed(server.hostname, amount, newStage - 1, fmtDay(suspendAt), billingUrl()),
    );
  } else {
    await mail(
      server.user.email,
      server.userId,
      method === "paypal"
        ? emails.paypalPaymentFinalNotice(server.hostname, amount, billingUrl())
        : emails.paymentFinalNotice(server.hostname, amount, billingUrl()),
    );
  }

  const methodLabel = method === "paypal" ? "PayPal" : "card";
  await notify(
    server.userId,
    `${server.hostname} — ${methodLabel} payment ${newStage >= DUNNING_EXHAUSTED ? "failed, final notice" : "declined"}`,
    newStage >= DUNNING_EXHAUSTED
      ? `We've run out of automatic attempts for ${amount}. ${server.hostname} is still running — settle the balance to keep it that way.`
      : `We couldn't charge ${amount} to your ${methodLabel}. Nothing is suspended; we'll try again on ${fmtDay(scheduledAt)}.`,
    `/dashboard/servers/${server.id}`,
  );
}

/**
 * When the Nth failed attempt should be followed by another one.
 *
 * Floored at MIN_RETRY_GAP_MS so a worker that has been down for a week does not
 * discover four overdue slots at once and fire the entire sequence — three charges
 * and three emails — inside a single afternoon.
 */
function nextRetryAt(expiresAt: Date, failures: number, now: Date): Date | null {
  if (failures >= DUNNING_EXHAUSTED) return null;
  const scheduled = new Date(expiresAt.getTime() + retryDayFor(failures) * DAY);
  const floor = new Date(now.getTime() + MIN_RETRY_GAP_MS);
  return scheduled > floor ? scheduled : floor;
}

/**
 * Move the next attempt WITHOUT spending a dunning attempt, keeping the in-memory
 * row in step with the write.
 *
 * The mirroring is load-bearing, not tidiness: `suspendDueAt` runs a few lines
 * later in the SAME pass and reads `dunningNextAt` to decide whether an attempt we
 * have promised is still outstanding. Reading the pre-update value there would
 * suspend a server seconds after we committed to trying its card again.
 */
async function rescheduleAttempt(server: DueServer, at: Date | null): Promise<void> {
  await db.server.update({ where: { id: server.id }, data: { dunningNextAt: at } });
  server.dunningNextAt = at;
}

/* ------------------------------------------------------------------ *
 * Suspension
 * ------------------------------------------------------------------ */

/**
 * When this overdue server may be paused — null means never (auto-suspend is off).
 *
 * With a card in play the deadline is CARD_SUSPEND_DAY past expiry: one clear day
 * after the final-notice email, so the customer always gets a full day with the
 * warning in hand before anything stops. Without a card there is nothing to wait
 * for beyond the configured grace period.
 *
 * The deadline also never lands BEFORE a date we have promised the customer. A
 * worker that was down for the first five days starts the sequence late, and
 * suspending on the calendar alone would then pause a server minutes after emailing
 * "we'll try your card again on <date>" or "this is your final notice" — the exact
 * broken promise this whole feature exists to stop. `dunningNextAt` carries that
 * promise (the next attempt while any remain, the clear day once they are spent),
 * and the slip it can buy is capped by SUSPEND_SLIP_CAP_DAYS so a permanently
 * failing Stripe cannot defer suspension forever.
 */
function suspendDueAt(
  server: { expiresAt: Date | null; dunningStage: number; dunningNextAt: Date | null },
  hasCard: boolean,
  cfg: DunningConfig,
): Date | null {
  if (!cfg.autoSuspend || !server.expiresAt) return null;
  const days = calendarSuspendDay(cfg, hasCard);
  const at = new Date(server.expiresAt.getTime() + days * DAY);
  if (!hasCard || !server.dunningNextAt || server.dunningNextAt <= at) return at;
  const cap = new Date(server.expiresAt.getTime() + (days + SUSPEND_SLIP_CAP_DAYS) * DAY);
  return server.dunningNextAt < cap ? server.dunningNextAt : cap;
}

/**
 * Days past expiry of the plain calendar deadline, before any late-sequence slip.
 * One expression, because `suspendDueAt` and the exhausted-sequence bookkeeping in
 * `recordDeclinedAttempt` must agree on it exactly or a server can be scheduled to
 * pause on a day the suspension check does not recognise.
 */
function calendarSuspendDay(cfg: DunningConfig, hasCard: boolean): number {
  return hasCard ? Math.max(cfg.graceDays, CARD_SUSPEND_DAY) : cfg.graceDays;
}

/**
 * Pause an unpaid server: mark it, queue the SUSPEND job, tell the customer.
 *
 * `suspendReason: "UNPAID"` is load-bearing, not a label. It is what scopes
 * `terminateOverdue` (below) and the auto-unsuspend in `renewNow` to billing
 * suspensions only, so an abuse or admin suspension can never be deleted by the
 * overdue sweep nor lifted by a customer paying a bill.
 */
async function suspendUnpaid(server: DueServer, cfg: DunningConfig): Promise<void> {
  if (!cfg.autoSuspend) return; // admin kill switch — belt and braces
  // Never queue a second SUSPEND behind one that is already queued or running:
  // duplicate jobs against one VM are how a suspend/unsuspend race leaves a paid-up
  // customer offline.
  const pending = await db.job.count({
