"use client";

import { useActionState, useState, useTransition } from "react";
import {
  toggleAutoRenew,
  renewNow,
  adminExtendServer,
  adminSetServerFree,
  adminSetGrandfatheredPrice,
  adminClearGrandfatheredPrice,
} from "@/lib/actions";

export function RenewalCard({
  serverId,
  autoRenew,
  expiresAt,
  priceCents,
  extraDiskMonthlyCents = 0,
  extraDiskGB = 0,
  suspendedUnpaid,
  renewTotalCents,
  renewDurationLabel,
}: {
  serverId: string;
  autoRenew: boolean;
  expiresAt: string | null;
  priceCents: number;
  /**
   * What "Renew now" ACTUALLY charges, and the term it actually buys — computed
   * server-side by the same `renewalQuote()` the action charges through.
   *
   * Real incident, 2026-07-26 QA: this card rendered the literal string
   * "+30 days" beside the plan's MONTHLY price, while `renewNow` has always
   * charged a full term. "Renew now (+30 days, $8.99)" took **$97.09** and moved
   * the expiry twelve months — 10.8× on Starter/12mo, 28.8× on Max/36mo, with no
   * confirmation between the click and the debit. Never re-derive these two
   * numbers in this component; they belong to the action, and a second
   * derivation is exactly how they drifted.
   */
  renewTotalCents: number;
  renewDurationLabel: string;
  /**
   * Monthly surcharge for permanently-added disk. Billed on TOP of the plan every
   * cycle (worker/billing.ts + renewNow), so the card must show the real total —
   * otherwise the quoted renewal price would be lower than the charge.
   */
  extraDiskMonthlyCents?: number;
  extraDiskGB?: number;
  suspendedUnpaid: boolean;
}) {
  const [pending, start] = useTransition();
  const [error, setError] = useState<string | null>(null);
  const totalMonthlyCents = priceCents + extraDiskMonthlyCents;

  return (
    <div className="card">
      <h2 className="mb-3 font-semibold">Subscription</h2>
      {error && (
        <div className="mb-3 rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">
          {error}
        </div>
      )}
      <dl className="space-y-2 text-sm">
        <div className="flex justify-between">
          <dt className="text-slate-400">Price</dt>
          <dd>${(totalMonthlyCents / 100).toFixed(2)}/mo</dd>
        </div>
        {extraDiskMonthlyCents > 0 && (
          <div className="flex justify-between text-xs text-slate-500">
            <dt>
              incl. {extraDiskGB} GB added storage <span className="text-slate-600">(permanent)</span>
            </dt>
            <dd>${(extraDiskMonthlyCents / 100).toFixed(2)}/mo</dd>
          </div>
        )}
        <div className="flex justify-between">
          <dt className="text-slate-400">Paid until</dt>
          <dd>{expiresAt ? expiresAt.slice(0, 10) : "—"}</dd>
        </div>
        <div className="flex items-center justify-between">
          <dt className="text-slate-400">Auto-renew</dt>
          <dd>
            <button
              className={autoRenew ? "btn-secondary py-1" : "btn-primary py-1"}
              disabled={pending}
              onClick={() => start(() => toggleAutoRenew(serverId))}
            >
              {autoRenew ? "On — turn off" : "Off — turn on"}
            </button>
          </dd>
        </div>
      </dl>
      <button
        className="btn-primary mt-4 w-full"
        disabled={pending}
        onClick={() => {
          // An irreversible wallet debit gets one confirmation stating the real
          // amount and the real duration. There was none, and the label was
          // wrong by an order of magnitude — see the prop docs above.
          const ok = window.confirm(
            suspendedUnpaid
              ? `Pay $${(renewTotalCents / 100).toFixed(2)} now to restore this server and extend it by ${renewDurationLabel}?`
              : `Renew this server for ${renewDurationLabel}?\n\n$${(renewTotalCents / 100).toFixed(2)} will be taken from your wallet now.`
          );
          if (!ok) return;
          start(async () => {
            setError(null);
            const res = await renewNow(serverId);
            if (res?.error) setError(res.error);
          });
        }}
      >
        {pending
          ? "Working…"
          : suspendedUnpaid
            ? `Pay $${(renewTotalCents / 100).toFixed(2)} & restore server`
            : `Renew now (+${renewDurationLabel}, $${(renewTotalCents / 100).toFixed(2)})`}
      </button>
    </div>
  );
}

export function ExtendForm({ serverId }: { serverId: string }) {
  const [state, action, pending] = useActionState(adminExtendServer, {});
  return (
    <form action={action} className="flex items-center gap-2">
      <input type="hidden" name="serverId" value={serverId} />
      <input className="input w-20 py-1" name="days" type="number" placeholder="±days" />
      <button className="btn-secondary py-1" disabled={pending}>
        Extend
      </button>
      {state?.error && <span className="text-xs text-red-400">{state.error}</span>}
    </form>
  );
}

/**
 * Set/clear a server's locked renewal rate (`Server.grandfatheredRenewalCents`)
 * — the admin surface for honoring an informal "you keep your old price"
 * arrangement. See `adminSetGrandfatheredPrice`'s doc comment (lib/actions.ts)
 * for why this reuses that one field rather than adding a second.
 */
export function GrandfatheredPriceForm({
  serverId,
  currentCents,
}: {
  serverId: string;
  currentCents: number | null;
}) {
  const [state, action, pending] = useActionState(adminSetGrandfatheredPrice, {});
  const [clearPending, startClear] = useTransition();
  return (
    <div className="space-y-2">
      {currentCents != null && (
        <div className="flex flex-wrap items-center gap-2 text-sm">
          <span className="text-slate-400">Locked at</span>
          <span className="font-mono font-medium text-brand-300">${(currentCents / 100).toFixed(2)}/mo</span>
          <button
            type="button"
            className="btn-secondary py-1 text-xs"
            disabled={clearPending}
            onClick={() => {
              if (
                window.confirm(
                  "Clear the locked price? This server will go back to renewing at the live plan price.",
                )
              )
                startClear(() => adminClearGrandfatheredPrice(serverId));
            }}
          >
            {clearPending ? "Working…" : "Clear"}
          </button>
        </div>
      )}
      <form action={action} className="flex flex-wrap items-center gap-2">
        <input type="hidden" name="serverId" value={serverId} />
        <span className="text-xs text-slate-500">$</span>
        <input
          className="input w-24 py-1"
          name="priceDollars"
          type="number"
          step="0.01"
          min="0"
          placeholder={currentCents != null ? (currentCents / 100).toFixed(2) : "e.g. 19.99"}
        />
        <span className="text-xs text-slate-500">/mo</span>
        <button className="btn-secondary py-1" disabled={pending}>
          {pending ? "Working…" : currentCents != null ? "Update locked price" : "Lock price"}
        </button>
        {state?.error && <span className="text-xs text-red-400">{state.error}</span>}
      </form>
    </div>
  );
}

export function FreeToggle({ serverId, isFree }: { serverId: string; isFree: boolean }) {
  const [pending, start] = useTransition();
  return (
    <button
      className="btn-secondary py-1"
      disabled={pending}
      onClick={() => {
        if (
          window.confirm(
            isFree
              ? "Convert to a PAID subscription? It will get a renewal date 30 days out."
              : "Make this server FREE? Billing stops and it never expires."
          )
        )
          start(() => adminSetServerFree(serverId, !isFree));
      }}
    >
      {isFree ? "Make paid" : "Make free"}
    </button>
  );
}

