/**
 * Admin-only "force this renewal right now" button — the counterpart to the
 * customer's own `RenewalCard` above, but wallet-then-card (via
 * `adminRenewServerNow` -> `renewServerImmediately`, worker/billing.ts)
 * instead of wallet-only, and usable whether or not the period has actually
 * expired yet. See `adminRenewServerNow`'s own doc comment (lib/actions.ts)
 * for why this exists alongside the automatic sweep rather than waiting for it.
 *
 * `preview` is computed server-side in app/admin/servers/[id]/page.tsx through
 * the SAME `renewalQuote`/`walletSplit` calls the action itself charges
 * through — never a second estimate, matching `RenewalCard`'s own real
 * incident lesson (a hardcoded label once took $97.09 while showing $8.99).
 */
export function AdminRenewNowButton({
  serverId,
  hostname,
  preview,
}: {
  serverId: string;
  hostname: string;
  preview: {
    totalCents: number;
    walletCents: number;
    cardCents: number;
    durationLabel: string;
    hasCard: boolean;
    cardLabel: string | null;
    coversFully: boolean;
  };
}) {
  const [pending, start] = useTransition();
  const [result, setResult] = useState<{ ok: boolean; message: string } | null>(null);

  // Mirrors the action's own guard (insufficient wallet AND no chargeable
  // card) — disabled here too so the confirm dialog is never reached for a
  // charge that is already known to fail.
  const canCharge = preview.coversFully || preview.hasCard;
  const splitLabel = preview.coversFully
    ? `$${(preview.totalCents / 100).toFixed(2)} wallet`
    : preview.hasCard
      ? `$${(preview.walletCents / 100).toFixed(2)} wallet + $${(preview.cardCents / 100).toFixed(2)} card`
      : `$${(preview.walletCents / 100).toFixed(2)} wallet — short $${(preview.cardCents / 100).toFixed(2)}, no card on file`;

  return (
    <div className="flex flex-col gap-1">
      <button
        type="button"
        className="btn-secondary py-1"
        disabled={pending || !canCharge}
        title={!canCharge ? "Insufficient wallet balance and no chargeable card on file — nothing to charge." : undefined}
        onClick={() => {
          // An irreversible real-money charge gets one confirmation stating the
          // real total and the real wallet/card split before it fires — same
          // discipline as the customer-facing button above.
          const ok = window.confirm(
            `Renew ${hostname} right now for ${preview.durationLabel}?\n\n` +
              `$${(preview.totalCents / 100).toFixed(2)} total — ${splitLabel}` +
              `${!preview.coversFully && preview.hasCard ? ` (${preview.cardLabel ?? "saved card"})` : ""}.\n\n` +
              `This charges real money immediately — it does not wait for the period to actually expire.`,
          );
          if (!ok) return;
          start(async () => {
            setResult(null);
            const res = await adminRenewServerNow(serverId);
            setResult(
              res.ok
                ? {
                    ok: true,
                    message: `Renewed via ${res.path} — $${(res.totalCents / 100).toFixed(2)} (wallet $${(res.walletCents / 100).toFixed(2)} + card $${(res.cardCents / 100).toFixed(2)}). New expiry ${res.newExpiry.slice(0, 10)}.`,
                  }
                : { ok: false, message: res.error },
            );
          });
        }}
      >
        {pending ? "Charging…" : `Renew now (${splitLabel})`}
      </button>
      {result && (
        <span className={`max-w-xs text-xs ${result.ok ? "text-emerald-400" : "text-red-400"}`}>{result.message}</span>
      )}
    </div>
  );
}

