import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { stripComments } from "./_source-tools.ts";
import { renewalCharge, type PricedServer, type RenewalPrices } from "../lib/renewal-charge.ts";
import { walletSplit, STRIPE_MIN_CENTS } from "../lib/wallet-split.ts";

/**
 * `adminRenewServerNow` (lib/actions.ts) + `renewServerImmediately` (worker/
 * billing.ts) — the admin "Renew now" action built 2026-09-25 so an admin can
 * force a specific customer's renewal to run right now (wallet, then the
 * saved card for the remainder) instead of waiting for the automatic sweep.
 *
 * Follows the SAME split as test/money-core-guards.test.ts and
 * test/retention-offer.test.ts, for the same reason: `lib/actions.ts` and
 * `worker/billing.ts` both import `./db` (Prisma), so importing either one
 * here would connect this suite to a real database the moment the test file
 * loads (test/api-http-surface.test.ts documents this rule for the whole
 * repo). So:
 *
 *  (a) the WALLET/CARD SPLIT ARITHMETIC this action relies on is asserted for
 *      real, by composing the actual pure `renewalCharge` + `walletSplit`
 *      functions against realistic admin scenarios (grandfathered price,
 *      retention discount, annual discount, game plan) — the exact same two
 *      calls `renewServerImmediately` makes, in the exact same order;
 *  (b) everything that can only run inside a live transaction or against a
 *      real Stripe account (which leg actually gets charged, a real decline,
 *      a real concurrent double-charge) is instead verified against a real,
 *      fully isolated database with Stripe TEST-mode keys — see
 *      scripts/verify-admin-renew-now.ts and the summary of that run in the
 *      PR/commit description, not re-mocked here;
