    termMonths: 1,
    extraDiskGB: 0,
    plan: { name: "Starter", priceCents: 1000 },
    gamePlan: null,
    dedicatedIp: null,
    wantsDedicatedIp: false,
    backupTier: "FREE" as PricedServer["backupTier"],
    ...overrides,
  };
}

test("wallet-only: a balance that covers the whole renewal produces cardCents 0", () => {
  const charge = renewalCharge(pricedServer(), BASE_PRICES);
  const split = walletSplit({ dueCents: charge.totalCents, balanceCents: 5000, useWallet: true });
  assert.equal(charge.totalCents, 1000);
  assert.equal(split.cardCents, 0, "wallet covers the $10.00 due — no card leg, no Stripe call");
  assert.equal(split.walletApplied, 1000);
});

test("wallet+card split: a partial balance leaves exactly the shortfall on the card", () => {
  const charge = renewalCharge(pricedServer({ termMonths: 12, plan: { name: "Pro", priceCents: 2000 } }), {
    ...BASE_PRICES,
    annualDiscountPct: 10,
  });
  const split = walletSplit({ dueCents: charge.totalCents, balanceCents: 500, useWallet: true });
  assert.equal(split.walletApplied, 500);
  assert.equal(split.cardCents, charge.totalCents - 500);
  assert.equal(split.walletApplied + split.cardCents, charge.totalCents, "wallet + card always sums to the exact renewal charge");
  assert.ok(split.cardCents >= STRIPE_MIN_CENTS, "sanity: this fixture's remainder clears Stripe's floor");
});

test("insufficient-balance-and-no-card shape: zero balance puts the ENTIRE due on the card leg", () => {
  const charge = renewalCharge(pricedServer(), BASE_PRICES);
  const split = walletSplit({ dueCents: charge.totalCents, balanceCents: 0, useWallet: true });
  assert.equal(split.walletApplied, 0);
  assert.equal(split.cardCents, charge.totalCents);
  // adminRenewServerNow's own guard (asserted above via source) is what turns
  // "cardCents > 0 and hasChargeableCard() is false" into the insufficientFunds
  // error — this proves the ARITHMETIC that guard is reading is correct.
});

test("grandfathered price wins over the live catalog price in the split adminRenewServerNow would compute", () => {
  const live = renewalCharge(pricedServer({ plan: { name: "Pro", priceCents: 4000 } }), BASE_PRICES);
  const grandfathered = renewalCharge(
    pricedServer({ plan: { name: "Pro", priceCents: 4000 }, grandfatheredRenewalCents: 1500 }),
    BASE_PRICES,
  );
  assert.equal(live.totalCents, 4000);
  assert.equal(grandfathered.totalCents, 1500, "the locked rate must win, exactly like every other renewal path");
  const split = walletSplit({ dueCents: grandfathered.totalCents, balanceCents: 10_000, useWallet: true });
  assert.equal(split.walletApplied, 1500, "the wallet must only ever be charged the GRANDFATHERED total, never the live catalog price");
});

test("a pending retention discount halves the total the split is computed against", () => {
  const full = renewalCharge(pricedServer(), BASE_PRICES);
  const discounted = renewalCharge(pricedServer({ pendingRenewalDiscountPercent: 50 }), BASE_PRICES);
  assert.equal(discounted.totalCents, full.totalCents / 2);
  const split = walletSplit({ dueCents: discounted.totalCents, balanceCents: 0, useWallet: true });
  assert.equal(split.cardCents, 500, "the card leg reflects the DISCOUNTED total, not the pre-discount list price");
});

test("a game server's split is computed off its FLAT game-plan price, never the base VPS plan", () => {
  const charge = renewalCharge(
    pricedServer({
      plan: { name: "Starter", priceCents: 899 }, // base VPS plan — must be ignored
      gamePlan: { name: "Minecraft", priceCents: 499, termMonths: 1 },
      annualDiscountPct: null,
    }),
    BASE_PRICES,
  );
  assert.equal(charge.totalCents, 499, "a game server renews at its game-plan price, not the 899c base plan");
  const split = walletSplit({ dueCents: charge.totalCents, balanceCents: 200, useWallet: true });
  assert.equal(split.walletApplied, 200);
  assert.equal(split.cardCents, 299);
});

