      const pm = await stripe().paymentMethods.attach(pmToken, { customer: customer.id });
      await db.user.update({
        where: { id: user.id },
        data: {
          stripeCustomerId: customer.id,
          stripePaymentMethodId: pm.id,
          cardBrand: pm.card?.brand ?? "visa",
          cardLast4: pm.card?.last4 ?? "0000",
          cardExpMonth: pm.card?.exp_month ?? 12,
          cardExpYear: pm.card?.exp_year ?? 2030,
        },
      });
      return await db.user.findUniqueOrThrow({ where: { id: user.id } });
    }
    return user;
  }

  async function makeServer(opts: {
    userId: string;
    hostname: string;
    expiresInMs: number; // negative = already expired
    grandfatheredRenewalCents?: number;
    pendingRenewalDiscountPercent?: number;
    gamePlanId?: string;
  }): Promise<DueServer> {
    await db.server.create({
      data: {
        name: opts.hostname,
        hostname: opts.hostname,
        userId: opts.userId,
        planId: plan.id,
        osTemplateId: osTemplate.id,
        gamePlanId: opts.gamePlanId,
        status: "RUNNING",
        expiresAt: new Date(Date.now() + opts.expiresInMs),
        grandfatheredRenewalCents: opts.grandfatheredRenewalCents,
        pendingRenewalDiscountPercent: opts.pendingRenewalDiscountPercent,
      },
    });
    const fresh = await db.server.findUniqueOrThrow({
      where: { hostname: opts.hostname },
      include: { plan: true, user: true, gamePlan: true, dedicatedIp: true },
    });
    return fresh;
  }

  const results: { scenario: string; ok: boolean; detail: string }[] = [];
  const report = (scenario: string, ok: boolean, detail: string) => {
    results.push({ scenario, ok, detail });
    console.log(`[verify] ${ok ? "PASS" : "FAIL"} — ${scenario}: ${detail}`);
  };

  // ---- 1. wallet-only ----------------------------------------------------
  {
    const user = await makeUser({ balanceCents: 5000 });
    const server = await makeServer({ userId: user.id, hostname: `verify-wallet-only-${Date.now()}`, expiresInMs: -1000 });
    const before = await db.user.findUniqueOrThrow({ where: { id: user.id } });
    const result = await renewServerImmediately(server, ctxFor());
    const after = await db.user.findUniqueOrThrow({ where: { id: user.id } });
    const wtx = await db.walletTransaction.findMany({ where: { userId: user.id }, orderBy: { createdAt: "desc" } });
    const ok =
      result.ok === true &&
      result.path === "wallet" &&
      result.cardCents === 0 &&
      before.balanceCents - after.balanceCents === result.totalCents &&
      wtx.every((t) => t.stripePaymentIntentId === null);
    report("wallet-only", ok, JSON.stringify(result) + ` balance ${before.balanceCents}->${after.balanceCents}`);
  }

  // ---- 2. wallet + card split, REAL Stripe test-mode charge --------------
  {
    const user = await makeUser({ balanceCents: 300, withCard: "visa" });
    const server = await makeServer({ userId: user.id, hostname: `verify-wallet-card-${Date.now()}`, expiresInMs: -1000 });
    const result = await renewServerImmediately(server, ctxFor());
    const wtx = await db.walletTransaction.findMany({ where: { userId: user.id }, orderBy: { createdAt: "asc" } });
    const cardCredit = wtx.find((t) => t.stripePaymentIntentId !== null);
    const ok =
      result.ok === true &&
      result.path === "wallet+card" &&
      result.walletCents === 300 &&
      result.cardCents === 700 &&
      !!cardCredit &&
      cardCredit.amountCents === 700;
    report(
      "wallet+card split (REAL Stripe test-mode PaymentIntent)",
      ok,
      JSON.stringify(result) + ` — WalletTransaction.stripePaymentIntentId=${cardCredit?.stripePaymentIntentId}`,
    );
  }

  // ---- 3. insufficient balance AND no chargeable card --------------------
  {
    const user = await makeUser({ balanceCents: 0 });
    const server = await makeServer({ userId: user.id, hostname: `verify-insufficient-${Date.now()}`, expiresInMs: -1000 });
    const result = await renewServerImmediately(server, ctxFor());
    const ok = result.ok === false && result.reason === "insufficientFunds";
    report("insufficient balance, no card", ok, JSON.stringify(result));
  }

  // ---- 4. declined card ----------------------------------------------------
  {
    const user = await makeUser({ balanceCents: 0, withCard: "declined" });
    const server = await makeServer({ userId: user.id, hostname: `verify-declined-${Date.now()}`, expiresInMs: -1000 });
    const result = await renewServerImmediately(server, ctxFor());
    const ok = result.ok === false && result.reason === "declined" && !!result.message;
    report("declined card (real Stripe test decline)", ok, JSON.stringify(result));
  }

  // ---- 5. double-charge protection: two concurrent calls -----------------
  {
    const user = await makeUser({ balanceCents: 5000 });
    const hostname = `verify-concurrent-${Date.now()}`;
    await makeServer({ userId: user.id, hostname, expiresInMs: -1000 });
    const readFresh = async () =>
      db.server.findUniqueOrThrow({
        where: { hostname },
        include: { plan: true, user: true, gamePlan: true, dedicatedIp: true },
      });
    const [s1, s2] = await Promise.all([readFresh(), readFresh()]);
    const [r1, r2] = await Promise.all([renewServerImmediately(s1, ctxFor()), renewServerImmediately(s2, ctxFor())]);
    const winners = [r1, r2].filter((r) => r.ok);
    const losers = [r1, r2].filter((r) => !r.ok);
    const after = await db.user.findUniqueOrThrow({ where: { id: user.id } });
    const wtx = await db.walletTransaction.findMany({ where: { userId: user.id } });
    const ok =
      winners.length === 1 &&
      losers.length === 1 &&
      !losers[0].ok &&
      losers[0].reason === "alreadyRenewed" &&
      wtx.length === 1 &&
      5000 - after.balanceCents === (winners[0] as any).totalCents;
    report(
      "concurrent double-call double-charge protection",
      ok,
      `winner=${JSON.stringify(winners[0])} loser=${JSON.stringify(losers[0])} walletTxCount=${wtx.length} balance=${after.balanceCents}`,
    );
  }

  // ---- 6. grandfathered price honored (not the live catalog price) -------
  {
    const user = await makeUser({ balanceCents: 5000 });
    const server = await makeServer({
      userId: user.id,
      hostname: `verify-grandfathered-${Date.now()}`,
      expiresInMs: -1000,
      grandfatheredRenewalCents: 250, // plan.priceCents is 1000 — must charge 250, not 1000
    });
    const result = await renewServerImmediately(server, ctxFor());
    const ok = result.ok === true && result.totalCents === 250;
    report("grandfathered price honored", ok, JSON.stringify(result));
  }

  // ---- 7. retention discount honored --------------------------------------
  {
    const user = await makeUser({ balanceCents: 5000 });
    const server = await makeServer({
      userId: user.id,
      hostname: `verify-retention-${Date.now()}`,
      expiresInMs: -1000,
      pendingRenewalDiscountPercent: 50, // plan.priceCents 1000 -> 500 expected
    });
    const result = await renewServerImmediately(server, ctxFor());
    const after = await db.server.findUniqueOrThrow({ where: { id: server.id } });
    const ok = result.ok === true && result.totalCents === 500 && after.pendingRenewalDiscountPercent === null;
    report("retention discount honored + cleared after use", ok, JSON.stringify(result));
  }

  // ---- 8. game plan flat price honored (not the base VPS plan) -----------
  {
    const user = await makeUser({ balanceCents: 5000 });
    const server = await makeServer({
      userId: user.id,
      hostname: `verify-gameplan-${Date.now()}`,
      expiresInMs: -1000,
      gamePlanId: gamePlan.id, // 499c, vs. plan.priceCents 1000c
    });
    const result = await renewServerImmediately(server, ctxFor());
    const ok = result.ok === true && result.totalCents === 499;
    report("game plan flat price honored over base VPS plan", ok, JSON.stringify(result));
  }

  // ---- 9. early renewal (expiresAt still in the future) works -------------
  {
    const user = await makeUser({ balanceCents: 5000 });
    const server = await makeServer({
      userId: user.id,
      hostname: `verify-early-${Date.now()}`,
      expiresInMs: 6 * 3600_000, // 6 hours from now — NOT expired yet
    });
    const result = await renewServerImmediately(server, ctxFor());
    const ok = result.ok === true && result.newExpiry.getTime() > server.expiresAt!.getTime();
    report("early renewal (expiresAt still in the future) succeeds", ok, JSON.stringify(result));
  }

  console.log("\n[verify] ===== SUMMARY =====");
  for (const r of results) console.log(`  ${r.ok ? "PASS" : "FAIL"}  ${r.scenario}`);
  const failed = results.filter((r) => !r.ok);
  console.log(`\n[verify] ${results.length - failed.length}/${results.length} scenarios passed.`);
  if (failed.length > 0) {
    console.error(`[verify] ${failed.length} scenario(s) FAILED — see detail above.`);
    process.exitCode = 1;
  }
}

main()
  .catch((e) => {
    console.error("[verify] fatal:", e);
    process.exitCode = 1;
  })
  .finally(async () => {
    await db.$disconnect();
  });

