if (opts.withCard) {
  const customer = await stripe().customers.create({ email: user.email, name: user.name });
  // `pm_card_visa` is Stripe's shortcut PaymentMethod id — safe to attach
  // directly, and it charges successfully later. The decline-simulating
  // shortcuts (`pm_card_chargeDeclined` etc.) are meant to be used ONLY as
  // a one-shot `payment_method` on a PaymentIntent — Stripe's risk checks
  // reject the ATTACH itself, before this script ever gets to simulate a
  // renewal declining. To exercise a card that was saved successfully and
  // declines LATER (the real-world shape a dunning decline actually takes),
  // create it from a raw decline-simulating TEST card number instead —
  // attach succeeds, and only the later off-session charge attempt declines.
  const pm =
    opts.withCard === "visa"
      ? await stripe().paymentMethods.attach("pm_card_visa", { customer: customer.id })
      : await (async () => {
          const created = await stripe().paymentMethods.create({
            type: "card",
            card: {
              number: opts.withCard === "declined" ? "4000000000000002" : "4000000000009995",
              exp_month: 12,
              exp_year: 2030,
              cvc: "123",
            },
          });
          return stripe().paymentMethods.attach(created.id, { customer: customer.id });
        })();

