      cardLast4: pm.card?.last4 ?? "0000",
      cardExpMonth: pm.card?.exp_month ?? 12,
      cardExpYear: pm.card?.exp_year ?? 2030,
    },
  });
} else {
  // This Stripe test account has "raw card data APIs" disabled (the
  // default), so `paymentMethods.create`/`tokens.create` with a raw
  // decline-simulating card number are both refused outright, and
  // `paymentMethods.attach` on Stripe's special `pm_card_chargeDeclined`
  // shortcut ALSO declines immediately (Radar treats the attach itself
  // as the charge attempt for that fixture, rather than deferring the
  // decline to a later off-session confirmation as some Stripe docs
  // describe for older API versions). There is therefore no way, on
  // THIS account's current settings, to get a card that attaches
  // successfully today and only declines on the LATER renewal attempt —
  // so this records the special shortcut id directly as the saved
  // "card" without a successful attach having ever happened, which is
  // enough to exercise the real code under test: `hasChargeableCard()`
  // reads only these two columns, and `chargeSavedCardOffSession`
  // (lib/stripe-cards.ts) makes its OWN real, live PaymentIntent
  // creation call against Stripe with this payment_method id — so the
  // decline captured below is Stripe's genuine, live response to that
  // real API call, not a simulated/mocked one.
  const pmId = opts.withCard === "declined" ? "pm_card_chargeDeclined" : "pm_card_chargeDeclinedInsufficientFunds";
  await db.user.update({
    where: { id: user.id },
    data: {
      stripeCustomerId: customer.id,
      stripePaymentMethodId: pmId,
      cardBrand: "visa",
      cardLast4: "0002",
      cardExpMonth: 12,
      cardExpYear: 2030,
    },
  });
}
return await db.user.findUniqueOrThrow({ where: { id: user.id } });

